{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:umf:core:nullability-operation:1.0.0",
  "title": "Core nullability inspection and explicit author declaration results",
  "$defs": {
    "nullability": {
      "enum": [
        "required",
        "absent-allowed",
        "unspecified"
      ]
    },
    "identity": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "module",
        "element"
      ],
      "properties": {
        "module": {
          "type": "string",
          "minLength": 1
        },
        "element": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "source": {
      "oneOf": [
        {
          "$ref": "urn:umf:core:0.1.0"
        },
        {
          "$ref": "urn:umf:core:0.2.0"
        },
        {
          "$ref": "urn:umf:core:0.3.0"
        }
      ]
    },
    "lookup": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "operation",
        "version",
        "source",
        "identity",
        "path",
        "meaning",
        "provenance"
      ],
      "properties": {
        "operation": {
          "const": "inspect-core-nullability"
        },
        "version": {
          "const": "1.0.0"
        },
        "source": {
          "$ref": "#/$defs/source"
        },
        "identity": {
          "$ref": "#/$defs/identity"
        },
        "path": {
          "type": "string"
        },
        "provenance": {
          "const": "unverified"
        },
        "meaning": {
          "oneOf": [
            {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "state",
                "nullability"
              ],
              "properties": {
                "state": {
                  "const": "known"
                },
                "nullability": {
                  "$ref": "#/$defs/nullability"
                }
              }
            },
            {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "state"
              ],
              "properties": {
                "state": {
                  "const": "missing"
                }
              }
            },
            {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "state",
                "value"
              ],
              "properties": {
                "state": {
                  "const": "legacy"
                },
                "value": {}
              }
            },
            {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "state",
                "value"
              ],
              "properties": {
                "state": {
                  "const": "unknown"
                },
                "value": {
                  "type": "string",
                  "minLength": 1,
                  "not": {
                    "$ref": "#/$defs/nullability"
                  }
                }
              }
            },
            {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "state"
              ],
              "properties": {
                "state": {
                  "const": "inapplicable"
                }
              }
            }
          ]
        }
      }
    },
    "declaration": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "operation",
        "version",
        "source",
        "target",
        "identity",
        "provenance"
      ],
      "properties": {
        "operation": {
          "const": "declare-core-nullability"
        },
        "version": {
          "const": "1.0.0"
        },
        "source": {
          "$ref": "urn:umf:core:0.3.0"
        },
        "target": {
          "$ref": "urn:umf:core:0.3.0"
        },
        "identity": {
          "$ref": "#/$defs/identity"
        },
        "provenance": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "origin",
            "idealPath",
            "nullability",
            "binding",
            "basis",
            "nativePath"
          ],
          "properties": {
            "origin": {
              "const": "authored"
            },
            "idealPath": {
              "type": "string"
            },
            "nullability": {
              "$ref": "#/$defs/nullability"
            },
            "binding": {
              "const": {
                "id": "umf.core.nullability.authoring",
                "version": "1.0.0"
              }
            },
            "basis": {
              "const": "explicit-author-declaration"
            },
            "nativePath": {
              "type": "null"
            }
          }
        }
      }
    }
  },
  "oneOf": [
    {
      "$ref": "#/$defs/lookup"
    },
    {
      "$ref": "#/$defs/declaration"
    }
  ]
}
